export const learnCourses = courses.filter((course, index, all) => all.findIndex((candidate) => candidate.slug === course.slug) === index);
export const learnCategories: LearnCategory[] = ["Bible", "Prayer", "Faith", "Christian Life", "Family", "Children", "Leadership", "Service"];
export const learnLevels: LearnLevel[] = ["Beginner", "Intermediate", "Advanced"];

export function getCourse(slug: string | undefined): LearnCourse | undefined { return learnCourses.find((course) => course.slug === slug); }
export function getLesson(course: LearnCourse, slug: string | undefined): LearnLesson | undefined { return course.lessons.find((item) => item.slug === slug); }
export function getCourseLessons(course: LearnCourse): LearnLesson[] {
  const byId = new Map(course.lessons.map((item) => [item.id, item]));
  return course.modules.flatMap((module) => module.lessonIds.map((id) => byId.get(id)).filter((item): item is LearnLesson => Boolean(item)));
}